#!/usr/bin/env python3
"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import re
import sys


def nid(s):
    return str(s).strip().casefold()


def fold(s):
    s = str(s).casefold()
    s = "".join(ch if ch.isalnum() else " " for ch in s)
    return " ".join(s.split())


def read_batch(path):
    """Return (batch, revision, status, records); record = (ballot, contest, marks)
    with marks a list of (rank, kind, value)."""
    with open(path, encoding="utf-8", newline="") as f:
        text = f.read()
    lines = text.replace("\r\n", "\n").split("\n")
    recs = []
    if path.endswith(".jsonl"):
        head = None
        for ln in lines:
            if not ln.strip():
                continue
            o = json.loads(ln)
            if head is None:
                head = o
                continue
            marks = []
            for m in o.get("marks", []):
                r = int(m["rank"])
                if m.get("write_in") is not None:
                    marks.append((r, "wi", m["write_in"]))
                elif m.get("candidate") is not None:
                    marks.append((r, "c", m["candidate"]))
            recs.append((o["ballot"], o["contest"], marks))
        meta = head or {}
    else:
        meta = {}
        i = 0
        while i < len(lines) and (lines[i].startswith("#") or not lines[i].strip()):
            ln = lines[i]
            if ln.startswith("#") and ":" in ln:
                k, v = ln[1:].split(":", 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
        body = "\n".join(lines[i:])
        rd = csv.reader(io.StringIO(body, newline=""))
        header = None
        for row in rd:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [c.strip() for c in row]
                continue
            d = dict(zip(header, row))
            marks = []
            for col, cell in d.items():
                m = re.fullmatch(r"rank(\d+)", col)
                if not m or cell is None or not cell.strip():
                    continue
                r = int(m.group(1))
                for part in cell.split("|"):
                    p = part.strip()
                    if not p:
                        continue
                    if p[:3].upper() == "WI:":
                        marks.append((r, "wi", p[3:]))
                    else:
                        marks.append((r, "c", p))
            recs.append((d["ballot"].strip(), d["contest"].strip(), marks))
    return (str(meta.get("batch")), int(str(meta.get("revision")).strip()),
            str(meta.get("status", "final")).strip().lower(), recs)


class Contest:
    def __init__(self, c):
        self.id = c["id"]
        self.max_ranks = int(c["max_ranks"])
        self.names = {}      # normalized id -> id as written
        self.withdrawn = set()
        for cand in c.get("candidates", []):
            n = nid(cand["id"])
            self.names[n] = cand["id"]
            if cand.get("status", "active") == "withdrawn":
                self.withdrawn.add(n)
        self.wi_text = {}
        for w in c.get("write_ins", []):
            n = nid(w["id"])
            self.names[n] = w["id"]
            for t in [w["name"]] + list(w.get("aliases", [])):
                self.wi_text.setdefault(fold(t), n)
        self.lot = [nid(x) for x in c.get("lot_order", [])]
        self.continuing0 = [n for n in self.names if n not in self.withdrawn]
        self.records = []

    def read_ballot(self, marks):
        """Return list of rankings: ('skip',) ('pass',) ('choice', c) ('over',)"""
        by_rank = {}
        for r, kind, v in marks:
            if 1 <= r <= self.max_ranks:
                by_rank.setdefault(r, []).append((kind, v))
        seen = set()
        out = []
        for r in range(1, self.max_ranks + 1):
            s = set()
            for kind, v in by_rank.get(r, []):
                if kind == "wi":
                    n = self.wi_text.get(fold(v))
                    if n is not None:
                        s.add(n)
                else:
                    s.add(nid(v))
            if not s:
                out.append(("skip",))
                continue
            s -= self.withdrawn
            if not s:
                out.append(("pass",))
                continue
            after_b = set(s)
            s -= seen
            seen |= after_b
            if not s:
                out.append(("skip",))
            elif len(s) == 1:
                out.append(("choice", next(iter(s))))
            else:
                out.append(("over",))
        return out

    @staticmethod
    def count_for(rankings, cont):
        n = len(rankings)
        for i, rk in enumerate(rankings):
            t = rk[0]
            if t == "choice":
                if rk[1] in cont:
                    return rk[1]
            elif t == "over":
                return None
            elif t == "skip":
                if i + 1 >= n or rankings[i + 1][0] == "skip":
                    return None
        return None

    def run(self):
        ballots = [self.read_ballot(m) for m in self.records]
        total = len(ballots)
        cont = list(self.continuing0)
        rounds = []
        hist = []  # per round tallies
        winner = None
        while True:
            cs = set(cont)
            tally = {c: 0 for c in cont}
            active = 0
            for b in ballots:
                c = self.count_for(b, cs)
                if c is not None:
                    tally[c] += 1
                    active += 1
            hist.append(tally)
            rnd = {"round": len(rounds) + 1,
                   "tallies": {self.names[c]: v for c, v in tally.items()},
                   "exhausted": total - active, "eliminated": []}
            rounds.append(rnd)
            if active == 0 or not cont:
                break
            top = max(tally, key=lambda c: tally[c])
            if tally[top] * 2 > active or len(cont) == 1:
                winner = top
                break
            zeros = [c for c in cont if tally[c] == 0]
            if zeros:
                elim = zeros
            else:
                m = min(tally.values())
                tied = [c for c in cont if tally[c] == m]
                k = len(hist) - 2
                while len(tied) > 1 and k >= 0:
                    mm = min(hist[k][c] for c in tied)
                    tied = [c for c in tied if hist[k][c] == mm]
                    k -= 1
                if len(tied) > 1:
                    tied.sort(key=lambda c: self.lot.index(c) if c in self.lot else -1)
                    tied = [tied[-1]]
                elim = tied
            rnd["eliminated"] = sorted(self.names[c] for c in elim)
            cont = [c for c in cont if c not in elim]
        return {"contest": self.id, "ballots": total,
                "winner": self.names[winner] if winner is not None else None,
                "rounds": rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    contests = [Contest(c) for c in el["contests"]]
    byid = {c.id: c for c in contests}
    cvr = os.path.join(indir, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        batch, rev, status, recs = read_batch(p)
        if batch not in best or rev > best[batch][0]:
            best[batch] = (rev, status, recs)
    for rev, status, recs in best.values():
        if status == "void":
            continue
        for ballot, contest, marks in recs:
            if contest in byid:
                byid[contest].records.append(marks)
    result = {"election": el["election"], "contests": [c.run() for c in contests]}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
